using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class FloorWearCapture {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>R+"/Docs/Review/2026-11-09_FloorSurfaceWear/";
 static void Shot(string n,Vector3 pos,Vector3 to,float fov=82){var g=new GameObject("FloorReviewCamera"){hideFlags=HideFlags.HideAndDontSave};var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(to);c.fieldOfView=fov;c.nearClipPlane=.04f;c.farClipPlane=240;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Before()=>Run("before");public static object After()=>Run("after");
 static object Run(string phase){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");string original=SceneManager.GetActiveScene().path;int count=0;try{foreach(string f in new[]{"B5","B4"}){var s=EditorSceneManager.OpenScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_"+f+"_Circular.unity");var player=s.GetRootGameObjects().FirstOrDefault(g=>g.name.StartsWith("Player"));if(player)player.SetActive(false);float y=f=="B5"?-82:-66;var rooms=f=="B5"?JObject.Parse(File.ReadAllText(R+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"))["rooms"].Children<JProperty>().Select(p=>p.Value).ToArray():JObject.Parse(File.ReadAllText(R+"/SourceAssets/B4_LayoutPolish/layout.json"))["rooms"].ToArray();foreach(string code in new[]{"C01","C04","E02","W01"}){var r=f=="B5"?JObject.Parse(File.ReadAllText(R+"/SourceAssets/B5_CorridorOnlyGuidance/plan.json"))["rooms"][code]:rooms.Single(q=>(string)q["id"]==code);var center=new Vector3((float)r["x"],y,-(float)r["v"]);float a=(float)r["doors"][0]["angle"]*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Shot(phase+"_"+f+"_"+code,center+dir*((float)r["r"]-1.3f)+Vector3.up*1.65f,center+Vector3.up*.45f);count++;}
 var vl=new Vector3(44,y,28);if(f=="B5"){Shot(phase+"_"+f+"_Cargo",vl+new Vector3(.2f,1.70f,-4.4f),vl+new Vector3(0,1.0f,-1.7f),78);Shot(phase+"_"+f+"_CargoDetail",vl+new Vector3(.35f,1.30f,-3.2f),vl+new Vector3(-.35f,.50f,-1.8f),78);}else{Shot(phase+"_"+f+"_Cargo",vl+new Vector3(.65f,1.75f,3.5f),vl+new Vector3(0,1.05f,-1.4f),75);Shot(phase+"_"+f+"_CargoDetail",vl+new Vector3(.35f,1.65f,-.2f),vl+new Vector3(-1.3f,.38f,-2.3f),80);}count+=2;
 }}finally{EditorSceneManager.OpenScene(original);}return new{phase,images=count};}
}
